  @Test
  void erstelleRechnung_success_createsRechnungWithCorrectValues() {
    Auftrag auftrag = new Auftrag();
    auftrag.setId(1L);
    auftrag.setStatus(Auftrag.STATUS_FERTIG);
    List<Auftrag> liste = Collections.singletonList(auftrag);

    List<AuftragPosition> pos = new ArrayList<>();
    AuftragPosition p = new AuftragPosition();
    p.setMenge(2.0);
    p.setEinzelpreis(50.0); // 2*50 = 100 netto
    pos.add(p);
    auftrag.setPositionen(pos);

    Integer bestanden = 0;
    when(jdbcTemplate.query(contains(SQL_AUFTRAG), any(RowMapper.class), eq(1L))).thenReturn(liste);
    when(jdbcTemplate.query(contains(SQL_POSITION), any(RowMapper.class), eq(1L))).thenReturn(pos);
    when(jdbcTemplate.queryForObject(contains("COUNT(*) FROM rechnung"), eq(Integer.class), eq(1L)))
        .thenReturn(bestanden);
    when(jdbcTemplate.queryForObject(anyString(), eq(Integer.class), eq("R-" + JAHR + "-%")))
        .thenReturn(0);
    when(jdbcTemplate.queryForObject(anyString(), eq(Long.class), any(Object[].class)))
        .thenReturn(101L);

    List<Rechnung> rechnungList = new ArrayList<>();
    Rechnung r = new Rechnung();
    r.setId(101L);
    r.setRechnungNr("R-" + JAHR + "-0001");
    r.setSummeNetto(100.0);
    r.setUst(20.0);
    r.setSummeBrutto(120.0);
    rechnungList.add(r);

    when(jdbcTemplate.query(contains("FROM rechnung r"), any(RowMapper.class), eq(101L)))
        .thenReturn(rechnungList);

    Rechnung result = service.erstelleRechnung(1L);

    assertThat(result.getRechnungNr()).isEqualTo("R-" + JAHR + "-0001");
    assertThat(result.getSummeNetto()).isEqualTo(100.0);
    assertThat(result.getUst()).isEqualTo(20.0);
    assertThat(result.getSummeBrutto()).isEqualTo(120.0);
  }

