  @Test
  void getMonatsBericht_returns12Months() {
    List<MonatsBericht> berichte = new ArrayList<>();
    for (int m = 1; m <= 12; m++) {
      MonatsBericht b = new MonatsBericht();
      b.setMonat(m);
      berichte.add(b);
    }

    when(jdbcTemplate.query(
            anyString(), any(RowMapper.class), eq(2023), eq(2023), eq(2023), eq(2023)))
        .thenReturn(berichte);

    List<MonatsBericht> result = service.getMonatsBericht(2023);

    assertThat(result).hasSize(12);
    for (int i = 0; i < 12; i++) {
      assertThat(result.get(i).getMonat()).isEqualTo(i + 1);
    }
  }

